const crypto = require('crypto');
const fail = (statusCode, error) => [{ json: { ok: false, statusCode, error } }];
const authorization = $json.headers?.authorization ?? '';
if (!authorization.startsWith('Bearer ')) return fail(401, 'Sesión requerida.');
const secret = $env.JWT_SECRET;
if (!secret) return fail(500, 'JWT_SECRET no está configurado.');
try {
  const token = authorization.slice(7).trim();
  const [header, payloadPart, signature, extra] = token.split('.');
  if (!header || !payloadPart || !signature || extra) throw new Error();
  const expected = crypto.createHmac('sha256', secret).update(`${header}.${payloadPart}`).digest('base64url');
  const left = Buffer.from(signature);
  const right = Buffer.from(expected);
  if (left.length !== right.length || !crypto.timingSafeEqual(left, right)) throw new Error();
  const payload = JSON.parse(Buffer.from(payloadPart, 'base64url').toString('utf8'));
  if (!payload.exp || payload.exp <= Math.floor(Date.now() / 1000)) throw new Error();
  const role = String(payload.rol ?? payload.role ?? '').toUpperCase();
  const permissions = (Array.isArray(payload.permisos) ? payload.permisos : []).map(value => String(value).toLowerCase());
  if (role !== 'SUPERADMIN' && !permissions.includes('parqueadero.gestionar')) return fail(403, 'No tiene permisos para gestionar parqueadero.');

  const body = $json.body ?? {};
  const parkingUserId = Number(body.parkingUserId);
  const plate = String(body.plate ?? '').trim().toUpperCase().replace(/\s+/g, '');
  const type = String(body.type ?? '').toUpperCase();
  const brand = String(body.brand ?? '').trim();
  const model = String(body.model ?? '').trim();
  const color = String(body.color ?? '').trim();
  const isPrimary = body.isPrimary;
  if (!Number.isInteger(parkingUserId) || parkingUserId <= 0) return fail(400, 'Seleccione un usuario válido.');
  if (!/^[A-Z0-9-]{5,15}$/.test(plate)) return fail(400, 'Ingrese una placa válida.');
  if (!['AUTO', 'MOTO'].includes(type)) return fail(400, 'Seleccione un tipo de vehículo válido.');
  if (!brand || brand.length > 60 || !model || model.length > 60 || !color || color.length > 40) return fail(400, 'Complete correctamente marca, modelo y color.');
  if (typeof isPrimary !== 'boolean') return fail(400, 'Seleccione el uso del vehículo.');
  return [{ json: { ok: true, parkingUserId, plate, type, brand, model, color, isPrimary } }];
} catch {
  return fail(401, 'La sesión es inválida o ha vencido.');
}
